#!/usr/bin/env bash
set -euo pipefail

root="$(cd "$(dirname "$0")/../.." && pwd)"
source="$root/api/openapi.yaml"
generator="$root/scripts/ci/generate-contracts.sh"

# This check proves the source boundary. Generated files and old runtime
# files are deliberately not treated as evidence for the new contract.
test -s "$source"
test -s "$root/api/codegen.yaml"
test -x "$generator"

go_generated="$root/internal/transport/httpapi/generated/oapi.gen.go"
ts_generated="$root/frontend/src/lib/api/generated.ts"
test -s "$go_generated"
test -s "$ts_generated"

grep -Fq 'output: internal/transport/httpapi/generated/oapi.gen.go' "$root/api/codegen.yaml"
grep -Fq 'Code generated by github.com/oapi-codegen/oapi-codegen/v2' "$go_generated"
grep -Fq 'package generated' "$go_generated"
grep -Fq 'This file was auto-generated by openapi-typescript' "$ts_generated"
grep -Fq 'src/lib/api/generated.ts' "$generator"
for marker in '"/anime/rss-list-view"' '"/anime/subscribe"' '"/anime/{managed_anime_id}/subgroups"'; do
  grep -Fq "$marker" "$ts_generated"
done
grep -Fq '(POST /anime/subscribe)' "$go_generated"
grep -Fq '(PATCH /anime/{managed_anime_id}/subgroups)' "$go_generated"
grep -Fq '(POST /anime/{managed_anime_id}/releases/reevaluate)' "$go_generated"
# P3.1: the synchronous reconciliation scan/apply paths are deleted; the
# async snapshot provider must be present instead.
grep -Fq '(POST /reconciliation/scans)' "$go_generated"
grep -Fq '(GET /reconciliation/scans/{managed_anime_id}/observations)' "$go_generated"
if rg -n '"/(settings|subscriptions|lifecycle|traces)' "$ts_generated"; then
  echo "generated TypeScript contract contains a retired or unimplemented path" >&2
  exit 1
fi
if rg -n '\((GET|POST|PUT|PATCH) /(settings|subscriptions|lifecycle|traces)' "$go_generated"; then
  echo "generated Go contract contains a retired or unimplemented path" >&2
  exit 1
fi
if grep -Fq 'frontend/src/api/generated.ts' "$generator"; then
  echo "legacy TypeScript contract output path is still configured" >&2
  exit 1
fi

ruby - "$source" <<'RUBY'
require "yaml"

source = ARGV.fetch(0)
doc = YAML.load_file(source)
abort "OpenAPI must be 3.1.0" unless doc.fetch("openapi") == "3.1.0"
abort "server must be /api/v1" unless doc.fetch("servers").map { |server| server.fetch("url") } == ["/api/v1"]

