# The path universe below is the OpenAPI contract only. The raw ServeMux mount
# /api/v1/mcp (internal/transport/httpapi/server.go Handler) is deliberately
# NOT an OpenAPI path: the in-process MCP server is an always-on implementation
# detail with its own request protocol, so it is exempt from the path-set check
# by construction — this script never inspects the Go runtime route table.
paths = doc.fetch("paths")
abort "unexpected paths in contract: #{paths.keys - required_paths.keys}" unless paths.keys.sort == required_paths.keys.sort
required_paths.each do |path, methods|
  actual = paths.fetch(path).keys & %w[get post put patch delete options head trace]
  abort "wrong methods for #{path}" unless actual.sort == methods.sort
end
%w[
  /observability/records
  /observability/diagnostics
].each do |path|
  refs = paths.fetch(path).fetch("get").fetch("parameters").map { |parameter| parameter["$ref"] }.compact
  %w[Cursor Limit FromTime ToTime].each do |name|
    abort "#{path} must reference #{name}" unless refs.include?("#/components/parameters/#{name}")
  end
end
%w[
  /plugin-targets/{plugin_target_id}
  /plugin-targets/{plugin_target_id}/test
].each do |path|
  refs = paths.fetch(path).values.first.fetch("parameters").map { |parameter| parameter["$ref"] }.compact
  abort "#{path} must reference PluginTargetID" unless refs.include?("#/components/parameters/PluginTargetID")
end
abort "delivery detail must reference PluginDeliveryID" unless paths.fetch("/plugin-deliveries/{plugin_delivery_id}").fetch("get").fetch("parameters").any? { |parameter| parameter["$ref"] == "#/components/parameters/PluginDeliveryID" }
abort "notification catalog must reference TriggerKindPath" unless paths.fetch("/template-catalogs/notification/{trigger_kind}").fetch("get").fetch("parameters").any? { |parameter| parameter["$ref"] == "#/components/parameters/TriggerKindPath" }

operations = paths.values.flat_map { |path| path.values.select { |value| value.is_a?(Hash) && value.key?("operationId") } }
operation_ids = operations.map { |operation| operation.fetch("operationId") }
abort "operationId values must be unique" unless operation_ids.uniq.length == operation_ids.length
stream = paths.fetch("/events/stream").fetch("get")
abort "SSE stream operationId drifted" unless stream.fetch("operationId") == "streamEvents"
stream_content = stream.fetch("responses").fetch("200").fetch("content")
abort "SSE stream must use text/event-stream" unless stream_content.key?("text/event-stream")

components = doc.fetch("components")
schemas = components.fetch("schemas")

# Resolve every local JSON pointer so a newly added component cannot hide a
# broken reference. Component schemas are validated here, but never treated as
# additional HTTP paths.
pointer_node = lambda do |ref|
  abort "external or malformed $ref: #{ref.inspect}" unless ref.is_a?(String) && ref.start_with?("#/")
  node = doc
  ref[2..-1].split("/").each do |part|
    key = part.gsub("~1", "/").gsub("~0", "~")
    begin
      node = node.fetch(key)
    rescue KeyError
      abort "unresolved $ref: #{ref}"
    end
  end
  node
end
refs = []
walk = lambda do |value|
  case value
  when Hash
    refs << value.fetch("$ref") if value.key?("$ref")
    value.each_value { |child| walk.call(child) }
  when Array
    value.each { |child| walk.call(child) }
  end
end
walk.call(doc)
refs.uniq.each { |ref| pointer_node.call(ref) }
resolve = lambda { |value| value.is_a?(Hash) && value.key?("$ref") ? pointer_node.call(value.fetch("$ref")) : value }
enum_values = lambda { |value| resolve.call(value).fetch("enum") }
required_fields = lambda { |schema| Array(schema["required"]) }
is_nullable = lambda do |schema|
  next true if schema.is_a?(Hash) && schema["nullable"] == true

  one_of = schema.is_a?(Hash) && schema["oneOf"]
  next false unless one_of.is_a?(Array)

  one_of.any? { |member| member.is_a?(Hash) && member["type"] == "null" } &&
    one_of.any? { |member| member.is_a?(Hash) && member.key?("$ref") }
end
assert_object = lambda do |name, required, properties|
  schema = schemas.fetch(name)
  abort "#{name} must be an object" unless schema["type"] == "object"
  abort "#{name} must reject additional properties" unless schema["additionalProperties"] == false
  required.each { |field| abort "#{name} must require #{field}" unless required_fields.call(schema).include?(field) }
  properties.each { |field| abort "#{name} must expose #{field}" unless schema.fetch("properties").key?(field) }
  schema
end
assert_optional_nullable = lambda do |name, field|
  schema = schemas.fetch(name)
  abort "#{name}.#{field} must be optional" if required_fields.call(schema).include?(field)
  property = schema.fetch("properties").fetch(field)
  resolved = resolve.call(property)
  abort "#{name}.#{field} must be nullable" unless is_nullable.call(property) || is_nullable.call(resolved)
end
assert_enum = lambda do |name, expected|
  abort "#{name} enum drifted" unless enum_values.call(schemas.fetch(name)) == expected
end

required_schemas = %w[
  ManagedAnime Subscription AnimeMetadata RSSSource RSSSourceRuntime Release
  DownloadTask Artifact FileOperation AnimeDraft SubscribeResult RSSListView
  SubscriptionLogEntry RoutineActivity DiagnosticEpisode ObservabilityRecord
  ObservabilityRecordPage DiagnosticEpisodePage PluginTargetConfig PluginTargetCreate PluginTargetUpdate
  PluginTargetTestInput PluginTargetPage PluginTestAccepted PluginDelivery PluginDeliveryAttempt PluginDeliveryDetail
  TelegramAdapterConfig FeishuAdapterConfig WebhookAdapterConfig PluginAdapterConfig
  TelegramSecretValue FeishuSecretValue WebhookSecretValue PluginAdapterSecretValue
  PluginTargetCreateSecret PluginTargetUpdateSecret NotificationEventTemplateDefault NotificationEventTemplateCustom
  NotificationTemplateSet NotificationEventTemplate NotificationTemplateCatalog NotificationTemplatePreview
  NotificationTemplatePreviewInput NamingTemplateCatalog NamingTemplatePreview NamingTemplatePreviewInput
  NamingCatalogField NamingCatalogFunction NamingCatalogSample
  NamingResolvedValue ArtifactFileSubtitleBinding NamingDiagnostic
  TemplateVariable TemplateFunction TemplateSampleFacts TemplateSourceError TemplateWarning
  ErrorResponse
  ProviderKind SubscriptionOrigin SubscriptionState SourceKind TMDBMediaKind SelectionMode
  GroupAction AutomationKind AutomationTrigger AutomationIntervalUnit AutomationState
  SubscriptionLogKind SubscriptionLogOutcome RoutineActivityKind RoutineActivityScopeKind RoutineActivityOutcome
  DiagnosticSeverity DiagnosticScopeKind PluginKind NotificationTriggerKind
  PluginAdapterKind PluginDeliveryKind PluginDeliveryState SubgroupScoreEntry SubgroupsSection
  NameKeywordRule ProviderNameKeywordRules ReleaseReevaluationResult
  DiscoverSubgroupsInput DiscoverSubgroupsOutcome DiscoverSubgroupsResult
  ReconciliationScanSubmitInput ReconciliationScanView ReconciliationObservation ReconciliationObservationPage
  ReleaseCandidateFactsView AcquisitionTarget TargetObservation
  MediaRecognitionPreviewInput MediaRecognitionPreviewResult ParserCatalogEntry
  FileMaintenancePolicyView FileMaintenancePolicyInput FileMaintenanceReplanInput
  FileMaintenanceReplanResult FileMaintenancePlanCandidate
  PlacementView PlacementCoverageView
  ReplacementDecisionView ReplacementEvaluateInput
  ReconciliationConsumerStateView AlignmentOperationView CleanupOperationView
  FileMaintenanceOverviewView
  RetentionAdmissionMode
  RetentionPolicyDefaultView RetentionPolicyDefaultInput
  InstanceRetentionPolicyView InstanceRetentionPolicyInput
  AcquireSeedOnceInput SelectedSeed SelectedSeedInput OneShotInputSnapshot OneShotAdmissionResult OneShotAcquisitionView
  SnapshotSeedProvider LibraryOverlap
]
required_schemas.each do |name|
  abort "required schema missing: #{name}" unless schemas.key?(name)
end

{
  "ProviderKind" => %w[anibt mikan],
  "SubscriptionOrigin" => %w[anibt mikan custom oneshot],
  "SubscriptionState" => %w[pending active stopped],
  "SourceKind" => %w[provider_group custom_rss],
  "TMDBMediaKind" => %w[tv movie],
  "SelectionMode" => %w[auto manual],
  "AutomationKind" => %w[group_discovery rss_refresh metadata_match catalog_refresh],
  "AutomationTrigger" => %w[scheduled manual],
  "AutomationIntervalUnit" => %w[minute hour day],
  "AutomationState" => %w[queued running completed partial failed],
  "SubscriptionLogOutcome" => %w[info success failure],
  "RoutineActivityKind" => %w[catalog_refresh provider_refresh rss_refresh metadata_match automation_dispatch retention_pass file_manager_operation],
  "RoutineActivityScopeKind" => %w[global automation provider subscription rss_source component],
  "RoutineActivityOutcome" => %w[success warning failure],
  "DiagnosticSeverity" => %w[warning error],
  "DiagnosticScopeKind" => %w[global provider subscription rss_source owner worker],
  "PluginKind" => %w[notification],
  "NotificationTriggerKind" => %w[download_submitted file_operation_completed file_operation_failed release_discovered download_failed subscription_changed unknown_files_imported],
  "PluginAdapterKind" => %w[telegram feishu webhook],
  "PluginDeliveryKind" => %w[business test],
  "PluginDeliveryState" => %w[pending delivering waiting_retry delivered failed unknown],
  "OneShotAcquisitionState" => %w[running retention_pending cleanup_blocked reclaiming cleaned],
  "OneShotTerminalOutcome" => %w[succeeded failed],
  "BroadcastDay" => %w[mon tue wed thu fri sat sun tbd none]
}.each { |name, expected| assert_enum.call(name, expected) }
assert_enum.call("DiscoverSubgroupsOutcome", %w[discovered no_groups provider_error config_error])
assert_enum.call("RetentionAdmissionMode", %w[all per_group single_copy])
# File manager: the ownership vocabulary is three states (MF1b removed
# `unclassified`: an unknown file is released at import). A released placement
# no longer owns its path, so the file reads as detached; `released` is a
# placement state, never an entry state.
assert_enum.call("FileManagerEntryState", %w[in_progress managed detached])
assert_enum.call("FileManagerOperation", %w[scan align copy move rename delete release match])
# P1 user operations: no overwrite choice exists, by design (§4.1, Q9).
assert_enum.call("FileManagerUserOperation", %w[move rename copy delete match])
# A match has its own endpoint; the plain-operation request can never carry it.
assert_enum.call("FileManagerOperationRequestKind", %w[move rename copy delete])
assert_enum.call("FileManagerMatchMediaKind", %w[tv])
assert_enum.call("FileManagerMatchBlockerCode", %w[facts_missing template_invalid target_invalid target_is_source])
assert_enum.call("FileManagerConflictChoice", %w[block version])
assert_enum.call("FileManagerOperationState", %w[ready running completed blocked failed])
assert_enum.call("FileManagerOperationFailure", %w[target_occupied source_changed source_missing source_managed execute_failed anime_unavailable])
%w[submitFileManagerOperation releaseFileManagerEntry alignFileManagerEntry matchFileManagerEntry].each do |operation_id|
  operation = paths.values.flat_map(&:values).find { |op| op.is_a?(Hash) && op["operationId"] == operation_id }
  abort "#{operation_id} is missing" unless operation
  params = Array(operation["parameters"]).map { |param| param["$ref"] ? param["$ref"].split("/").last : param["name"] }
  abort "#{operation_id} must require an idempotency key" unless params.any? { |name| name.to_s.downcase.include?("idempotency") }
end
abort "RetentionAdmissionMode enum drifted" unless enum_values.call(schemas.fetch("RetentionAdmissionMode")) == %w[all per_group single_copy]
%w[RetentionPolicyDefaultView InstanceRetentionPolicyView].each do |name|
  schema = schemas.fetch(name)
  abort "#{name} must reject additional properties" unless schema["additionalProperties"] == false
  abort "#{name} must expose the three complete business fields" unless %w[admission_mode quality_profile cleanup_policy].all? { |field| required_fields.call(schema).include?(field) }
  abort "#{name} must not carry the retired cutoff" if schema.fetch("properties").key?("cutoff")
end
abort "instance retention view must not ask the client to merge a default" if (schemas.fetch("InstanceRetentionPolicyView").fetch("properties").keys & %w[default inherit global override]).any?
%w[RetentionPolicyDefaultInput InstanceRetentionPolicyInput].each do |name|
  abort "#{name} must use expected-version CAS" unless required_fields.call(schemas.fetch(name)).include?("expected_version")
  abort "#{name} must require the three complete business fields" unless %w[admission_mode quality_profile cleanup_policy].all? { |field| required_fields.call(schemas.fetch(name)).include?(field) }
  abort "#{name} must not carry the retired cutoff" if schemas.fetch(name).fetch("properties").key?("cutoff")
end
assert_enum.call("SubscriptionLogKind", %w[
  subscription_created subscription_started subscription_stopped subscription_resumed metadata_applied
  group_changed policy_changed rss_new_content rss_refresh_failed release_processed
  download_changed artifact_verified placement_changed replacement_decided cleanup_completed
  file_alignment_completed file_alignment_failed acquisition_settled
])
abort "GroupAction action enum drifted" unless schemas.fetch("GroupAction").fetch("properties").fetch("action").fetch("enum") == %w[force_include force_exclude restore_auto]

managed_anime = assert_object.call("ManagedAnime", %w[id title version], %w[id title title_override version])
assert_optional_nullable.call("ManagedAnime", "title_override")

subscription = assert_object.call("Subscription", %w[id managed_anime_id origin state version new_releases_only], %w[id managed_anime_id origin origin_entry_ref instance_label state version new_releases_only start_baseline_at])
abort "Subscription origin must be canonical" unless enum_values.call(subscription.fetch("properties").fetch("origin")) == %w[anibt mikan custom oneshot]
abort "Subscription state must be pending|active|stopped" unless enum_values.call(subscription.fetch("properties").fetch("state")) == %w[pending active stopped]
%w[origin_entry_ref instance_label].each { |field| assert_optional_nullable.call("Subscription", field) }

metadata = assert_object.call("AnimeMetadata", %w[managed_anime_id version], %w[managed_anime_id bgm tmdb version])
metadata_draft = assert_object.call("AnimeMetadataDraft", [], %w[bgm tmdb])
%w[bgm tmdb].each do |field|
  assert_optional_nullable.call("AnimeMetadata", field)
