  node
end
candidate_id = unwrap.call(input_snapshot.fetch("properties").fetch("candidate_id"))
abort "OneShotInputSnapshot candidate_id must use ID" unless candidate_id.fetch("$ref").end_with?("/ID")
revision = unwrap.call(input_snapshot.fetch("properties").fetch("revision"))
abort "OneShotInputSnapshot revision must be int64" unless revision.fetch("type") == "integer" && revision.fetch("format") == "int64"
abort "OneShotInputSnapshot revision must have minimum 1" unless revision.fetch("minimum") == 1
%w[candidate_id revision input_source draft draft_digest parser target_facts].each do |field|
  assert_optional_nullable.call("OneShotInputSnapshot", field)
end
snapshot_draft = unwrap.call(input_snapshot.fetch("properties").fetch("draft"))
abort "OneShotInputSnapshot draft must use AnimeDraft" unless snapshot_draft.fetch("$ref").end_with?("/AnimeDraft")
assert_object.call(
  "OneShotAdmissionResult",
  %w[one_shot_id managed_anime_id subscription_id rss_source_id release_id state],
  %w[one_shot_id managed_anime_id subscription_id rss_source_id release_id download_task_id state]
)
assert_optional_nullable.call("OneShotAdmissionResult", "download_task_id")
one_shot_view = assert_object.call(
  "OneShotAcquisitionView",
  %w[one_shot_id state managed_anime_id subscription_id rss_source_id release_id version created_at updated_at],
  %w[input_snapshot one_shot_id state terminal_outcome terminal_reason_code terminal_reason managed_anime_id subscription_id rss_source_id release_id version download_task_id download_task artifact file_operation current_attempt_id failed_stage created_at updated_at]
)
%w[input_snapshot terminal_outcome terminal_reason_code terminal_reason download_task_id download_task artifact file_operation].each do |field|
  assert_optional_nullable.call("OneShotAcquisitionView", field)
end
# The read surface exposes the marker version as a required non-null integer.
unless required_fields.call(one_shot_view).include?("version")
  abort "OneShotAcquisitionView must require version"
end
one_shot_version = resolve.call(one_shot_view.fetch("properties").fetch("version"))
unless one_shot_version.fetch("type") == "integer" && one_shot_version.fetch("minimum") == 1
  abort "OneShotAcquisitionView.version must be a positive int64"
end

%w[
  /rss-source-runtimes/{rss_source_id}/retry
  /download-tasks/{download_task_id}/retry
  /artifacts/{artifact_id}/retry
].each do |path|
  operation = paths.fetch(path).fetch("post")
  retry_body = operation.fetch("requestBody").fetch("$ref")
  abort "#{path} must use owner-specific ManualRetry body" unless retry_body == "#/components/requestBodies/ManualRetry"
  parameter_refs = operation.fetch("parameters").map { |parameter| parameter["$ref"] }.compact
  abort "#{path} must require HTTP idempotency" unless parameter_refs.include?("#/components/parameters/IdempotencyKey")
end

# The record import retry is the only file-stage repair: version-guarded and
# idempotent, with no request body.
import_retry = paths.fetch("/acquisitions/{acquisition_id}/import/retry").fetch("post")
abort "import retry must not take a request body" if import_retry.key?("requestBody")
import_retry_params = import_retry.fetch("parameters").map { |parameter| parameter["$ref"] }.compact
%w[#/components/parameters/IfMatchVersion #/components/parameters/IdempotencyKey].each do |ref|
  abort "import retry must require #{ref}" unless import_retry_params.include?(ref)
end
%w[/file-operations/{file_operation_id}/retry /file-operations/{file_operation_id}/placement-retry /acquisitions/{acquisition_id}/completion/retry].each do |retired|
  abort "#{retired} is retired" if paths.key?(retired)
end

# Public schemas must not expose internal WorkItem lease/fencing/process data.
# EXEC-001 execution-attempt evidence is the one design-sanctioned exception:
# the bounded per-attempt terminal timestamp and stage are operator-facing
# recovery evidence (design section HTTP precise signatures), never a worker
# lease or fence. Every other schema keeps the blanket prohibition.
public_internal_fields = /\b(lease_until|fencing_token|max_attempts|expected_owner_version|terminal_at|process_instance|checkpoint)\b/i
sanctioned_attempt_schemas = %w[OneShotExecutionAttempt OneShotExecutionAttemptSummary OneShotExecutionAttemptPage]
schema_abort = lambda do
  schemas.each do |name, schema|
    next if sanctioned_attempt_schemas.include?(name)
    abort "public schema #{name} exposes internal WorkItem/process fields" if schema.to_s.match?(public_internal_fields)
  end
end
schema_abort.call
# The two attempt schemas may expose only the sanctioned terminal evidence; a
# worker lease/fence/process name is refused everywhere without exception.
strict = /\b(lease_until|fencing_token|max_attempts|expected_owner_version|process_instance|checkpoint)\b/i
if File.read(source).match?(strict)
  abort "public schemas expose internal WorkItem/process fields"
end
RUBY

forbidden='subscriptionplan|/subscriptions/plans|plan_id|plan_ref|plan_state|operational_state|peer[ _-]*subscription|lifecycletrace|release_events|/traces|\bactivity\b|\battention\b|generic[ _-]+command|generic[ _-]+(notification|event)|event[ _-]+subscription|outbound[ _-]*effect|arbitrary[ _-]+(script|payload|config)|process[ _-]*(instance|checkpoint)|/subscriptions/batch|replacement_scan|full[-_]library|task[-_]center|server[ _-]+draft|draft_id|/observability/tasks|workitemsummary|taskstatecounts|observabilitytaskpage'
if rg -n -i "$forbidden" "$source"; then
  echo "forbidden retired or generic shape found in OpenAPI source" >&2
  exit 1
fi

# MCP allowlist gate. The OpenAPI file is the only MCP allowlist: an operation
# is a tool by carrying `x-mcp`, a multi-step tool is a composite under
# `x-mcp-composites`. Every tool maps to exactly one operationId or one
# registered composite, every composite names existing operationIds, and the Go
# catalog builds the same tool set the server registers.
ruby - "$source" <<'RUBY'
require "yaml"

doc = YAML.load_file(ARGV.fetch(0))
groups = %w[subscription one_shot files records configuration]
ids = {}
tools = {}
doc.fetch("paths").each do |path, item|
  item.each do |method, op|
    next unless op.is_a?(Hash) && op["operationId"]
    ids[op["operationId"]] = true
    next unless op.key?("x-mcp")
    ext = op["x-mcp"]
    id = op["operationId"]
    abort "#{id}: x-mcp must be a mapping" unless ext.is_a?(Hash)
    tool = ext["tool"].to_s
    abort "#{id}: x-mcp.tool must be a snake_case name" unless tool.match?(/\A[a-z][a-z0-9]*(_[a-z0-9]+)*\z/)
    abort "#{id}: x-mcp.group must be one of #{groups.join(", ")}" unless groups.include?(ext["group"])
    abort "#{id}: x-mcp.write must be true or false" unless [true, false].include?(ext["write"])
    abort "#{id}: a GET operation cannot be a write tool" if method == "get" && ext["write"]
    abort "#{id}: x-mcp needs a description or the operation needs one" if ext["description"].to_s.strip.empty? && op["description"].to_s.strip.empty?
    abort "MCP tool #{tool} is declared by #{tools[tool]} and #{id}" if tools.key?(tool)
    tools[tool] = id
  end
end
composites = doc.fetch("x-mcp-composites", [])
composites.each do |composite|
  tool = composite["tool"].to_s
  abort "composite #{tool}: group must be one of #{groups.join(", ")}" unless groups.include?(composite["group"])
  abort "composite #{tool}: description is required" if composite["description"].to_s.strip.empty?
  abort "MCP tool #{tool} is declared twice" if tools.key?(tool)
  operations = Array(composite["operations"])
  abort "composite #{tool}: list the operationIds it composes" if operations.empty?
  operations.each { |id| abort "composite #{tool}: unknown operationId #{id}" unless ids[id] }
  tools[tool] = operations.join("+")
end
abort "the MCP allowlist is empty" if tools.empty?
RUBY
# Bearer scope gate (SEC-033). Every operation declares `x-scope`: `none`
# exactly for the anonymous operations (`security: []`), `read` for GET, `write`
# or `read` for the other methods, `secrets` only where named below (the raw
# token read and the backup export, download ticket and upload, since a backup
# holds every stored secret). A
# non-GET operation may be `read` only when the maintenance middleware lists it
# as side-effect free (readOnlyWritePathPatterns), and an MCP tool's
# `x-mcp.write` must equal `x-scope == write`. `x-secret` sits on string
# properties only; the pinned list and the masking behavior are tested in
# internal/transport/apiscope.
ruby - "$source" "$root/internal/transport/httpapi/middleware.go" <<'RUBY'
require "yaml"

doc = YAML.load_file(ARGV.fetch(0))
read_only_posts = File.read(ARGV.fetch(1)).scan(/`\^(\/api\/v1\/[^`]+)\$`/).flatten.map { |pattern| Regexp.new("\\A#{pattern}\\z") }
secrets_operations = %w[readApiTokenRaw exportBackup prepareBackupDownload restoreBackup]
bad = []
doc.fetch("paths").each do |path, item|
  item.each do |method, op|
    next unless op.is_a?(Hash) && op["operationId"]
    id = op["operationId"]
    scope = op["x-scope"]
    anonymous = op.key?("security") && Array(op["security"]).empty?
    concrete = "/api/v1" + path.gsub(/\{[^}]*\}/, "x")
    case
    when !%w[none read write secrets].include?(scope)
      bad << "#{id}: x-scope must be none, read, write or secrets (got #{scope.inspect})"
    when anonymous != (scope == "none")
      bad << "#{id}: x-scope none is exactly for the anonymous operations"
    when scope == "secrets" && !secrets_operations.include?(id)
      bad << "#{id}: x-scope secrets is reserved for #{secrets_operations.join(", ")}"
    when secrets_operations.include?(id) && scope != "secrets"
      bad << "#{id}: must declare x-scope secrets"
    when method == "get" && !%w[read secrets none].include?(scope)
      bad << "#{id}: a GET operation is read (or secrets)"
    when method != "get" && scope == "read" && !(method == "post" && read_only_posts.any? { |re| re.match?(concrete) })
      bad << "#{id}: #{method.upcase} #{path} is x-scope read but the maintenance middleware treats it as a product write"
    end
    if op["x-mcp"].is_a?(Hash) && op["x-mcp"]["write"] != (scope == "write")
      bad << "#{id}: x-mcp.write=#{op["x-mcp"]["write"]} disagrees with x-scope #{scope}"
    end
  end
end
walk = lambda do |node, trail|
  case node
  when Hash
    if node["x-secret"]
      bad << "#{trail}: x-secret must be true on a string property" unless node["x-secret"] == true && node["type"] == "string"
    end
    node.each { |key, child| walk.call(child, "#{trail}/#{key}") }
  when Array
    node.each_with_index { |child, index| walk.call(child, "#{trail}/#{index}") }
  end
end
walk.call(doc, "#")
unless bad.empty?
  warn bad
  abort "bearer scope gate failed"
end
RUBY
(cd "$root" && go test -count=1 ./internal/transport/apiscope >/dev/null) || {
  echo "bearer scope tests failed: x-scope/x-secret markers and the pinned lists disagree (go test ./internal/transport/apiscope)" >&2
  exit 1
}

# Tool results are the response body minus properties marked `x-mcp-omit`
# (download, feed and torrent URLs). The URL guard and the omission tests run
# here so a new response field cannot reach a tool unreviewed.
(cd "$root" && go test -count=1 ./internal/transport/mcp -run 'TestToolListPinsTheAllowlist|TestCatalogIsConsistentWithOpenAPI|TestInputSchemasAreWellFormed|TestAllowlistedResponsesDeclareNoDownloadURLFields|TestWithheldURLFieldsAreReachableOnlyThroughOmission|TestOmitMarkersArePropertyLevel|TestWithheldNamesCoverEveryOmittedProperty|TestKeepURLExemptionsArePinned' >/dev/null) || {
  echo "MCP catalog tests failed: the OpenAPI x-mcp allowlist, the x-mcp-omit markers and the registered tools disagree (go test ./internal/transport/mcp)" >&2
  exit 1
}

# Surface census gate: every operation needs a frontend, MCP or bansoko caller,
# or an `x-surface-keep: "<reason>"` on the OpenAPI operation. Run
# scripts/ci/census-surface.sh to see the full census.
if ! census_output="$("$root/scripts/ci/census-surface.sh" --check 2>&1 >/dev/null)"; then
  echo "surface census gate failed:" >&2
  printf '%s\n' "$census_output" >&2
  exit 1
fi

# Freshness: regenerate both outputs into a scratch root and prove the
# committed files match the OpenAPI source exactly.
scratch="$(mktemp -d)"
trap 'rm -rf "$scratch"' EXIT
# Keep the generator's output: a freshness failure that reports only "regeneration
# failed" is undiagnosable, and this lane has failed twice on CI with the same
# ~70-second fingerprint while the same command succeeds locally.
generator_log="$(mktemp)"
if ! BANSOKO_CONTRACT_OUT_ROOT="$scratch" "$generator" >"$generator_log" 2>&1; then
  echo "contract regeneration failed during freshness check" >&2
  echo "--- generator output (last 40 lines of $(wc -l <"$generator_log" | tr -d ' ') lines) ---" >&2
  tail -40 "$generator_log" >&2
  rm -f "$generator_log"
  exit 1
fi
rm -f "$generator_log"
for generated_path in \
  "internal/transport/httpapi/generated/oapi.gen.go" \
  "frontend/src/lib/api/generated.ts"; do
  if ! diff -q "$root/$generated_path" "$scratch/$generated_path" >/dev/null; then
    echo "generated contract out of sync: $generated_path (run scripts/ci/generate-contracts.sh)" >&2
    exit 1
  fi
done

# The repository skill is generated from the embedded agent guide and must match.
for skill_path in ".agents/skills/bansoko-agent/SKILL.md"; do
  if ! diff -q "$root/$skill_path" "$scratch/$skill_path" >/dev/null 2>&1; then
    echo "generated skill out of sync: $skill_path (run scripts/ci/generate-contracts.sh)" >&2
    exit 1
  fi
done

echo "OpenAPI source, canonical generator path, and generated freshness passed"
